from pathlib import Pathimport requestsfrom src import ollama_clientdef test_generate_copy_returns_model_response(tmp_path, monkeypatch):    image_path = tmp_path / "test.jpg"    image_path.write_bytes(b"fake image")    def mock_post(*args, **kwargs):        class MockResponse:            def raise_for_status(self):                pass            def json(self):                return {                    "message": {                        "content": "Copy generado de prueba."                    }                }        return MockResponse()    monkeypatch.setattr(        ollama_client.requests,        "post",        mock_post    )    result = ollama_client.generate_copy(        image_path,        "Genera un copy de prueba."    )    assert result == "Copy generado de prueba."    def test_generate_copy_handles_connection_error(tmp_path, monkeypatch):    image_path = tmp_path / "test.jpg"    image_path.write_bytes(b"fake image")    def mock_post(*args, **kwargs):        raise requests.exceptions.ConnectionError()    monkeypatch.setattr(        ollama_client.requests,        "post",        mock_post    )    try:        ollama_client.generate_copy(            image_path,            "Genera un copy de prueba."        )        assert False, "Se esperaba un RuntimeError"    except RuntimeError as error:        assert str(error) == (            "No se pudo conectar con Ollama. "            "Asegúrate de que Ollama esté ejecutándose."        )        def test_generate_copy_handles_timeout(tmp_path, monkeypatch):    image_path = tmp_path / "test.jpg"    image_path.write_bytes(b"fake image")    def mock_post(*args, **kwargs):        raise requests.exceptions.Timeout()    monkeypatch.setattr(        ollama_client.requests,        "post",        mock_post    )    try:        ollama_client.generate_copy(            image_path,            "Genera un copy de prueba."        )        assert False, "Se esperaba un RuntimeError"    except RuntimeError as error:        assert str(error) == (            "Ollama tardó demasiado en responder."        )